"""Hand-verified targeted cases for the tricky rules."""
import json
import subprocess
import sys
import zlib

sys.path.insert(0, "/app")
from main import solve

M = 0xFFFFFFFF
FAILS = []


def rec(plen, seq, kind, txid, payload, crc=None):
    hdr = plen.to_bytes(4, "little") + seq.to_bytes(4, "little") + bytes([kind]) + txid.to_bytes(4, "little")
    c = zlib.crc32(hdr + payload) & M if crc is None else crc
    return hdr + payload + c.to_bytes(4, "little")


def begin(seq, tx): return rec(0, seq, 1, tx, b"")
def abort(seq, tx): return rec(0, seq, 4, tx, b"")
def patch(seq, tx, pi, off, data):
    p = pi.to_bytes(2, "little") + off.to_bytes(2, "little") + len(data).to_bytes(2, "little") + data
    return rec(len(p), seq, 2, tx, p)
def patch_payload(pi, off, data):
    return pi.to_bytes(2, "little") + off.to_bytes(2, "little") + len(data).to_bytes(2, "little") + data
def commit(seq, tx, staged, count=None, digest=None):
    if count is None: count = len(staged)
    if digest is None: digest = zlib.crc32(b"".join(staged)) & M
    p = count.to_bytes(4, "little") + digest.to_bytes(4, "little")
    return rec(8, seq, 3, tx, p)


